// Changes: Read-only mode for the editor tabs in one place – the editor provides it from the project session
//          (session.readOnly); text fields in ui.tsx follow it by themselves and edit-only controls use <EditOnly>.

import { createContext, useContext, type ReactNode } from 'react'

const ReadOnlyContext = createContext(false)

export function ReadOnlyProvider({ value, children }: { value: boolean; children: ReactNode }) {
  return <ReadOnlyContext value={value}>{children}</ReadOnlyContext>
}

/** The shown content cannot be edited (e.g. a draft, for now). */
export const useReadOnly = () => useContext(ReadOnlyContext)

/** Renders controls that only change the content (examples, fill-in, clear, import) – hidden when read-only. */
export function EditOnly({ children }: { children: ReactNode }) {
  return useReadOnly() ? null : children
}
